    public static long oilObsHash(emon.Port.Cells cps, int start, int count) {
        long hash = -3750763034362895579L;
        int i = 0;
        while (i < count) {
            int cp = emon.Port.cellsAt(cps, start + i);
            if ((cp < 0) || ((cp > 1114111) || ((cp >= 55296) && (cp <= 57343)))) {
                cp = 65533;
            }
            if (cp < 128) {
                hash = oilHashByte(hash, cp);
            } else {
                int divisor = 64;
                int prefix = 192;
                if (cp >= 2048) {
                    divisor = 4096;
                    prefix = 224;
                }
                if (cp >= 65536) {
                    divisor = 262144;
                    prefix = 240;
                }
                hash = oilHashByte(hash, prefix + (cp / divisor));
                while (divisor > 1) {
                    divisor = divisor / 64;
                    hash = oilHashByte(hash, 128 + ((cp / divisor) % 64));
                }
            }
            i += 1;
        }
        return hash;
    }
