    public static int oilWalt(emon.Port.Cells c, int at, int word, int conf) {
        // Append alternatives before symbols and before starting the next word; insertion shifts later cells.
        int caps = oilGet(c, at, ohCaps());
        if (oilHas(caps, ocWalts()) == 0) {
            return -1;
        }
        int count = (word + oilWordBase(caps)) + -1;
        int p = oilWordText(c, at, word) - 1;
        oilInsert(c, p, conf);
        oilInsert(c, p + 1, 0);
        emon.Port.cellsSet(c, count, emon.Port.cellsAt(c, count) + 1);
        return p;
    }
